enum ParsedMetrics { Observed(PageSpeedMetrics), Unavailable, RuntimeFailure }
fn metrics(bytes:&[u8])->Result<ParsedMetrics> {
    let value:serde_json::Value=serde_json::from_slice(bytes)?;ensure!(value.is_object(),"Provider result must be an object");
    let Some(l)=value.get("lighthouseResult").filter(|v|!v.is_null())else{return Ok(ParsedMetrics::Unavailable)};ensure!(l.is_object(),"Invalid Lighthouse object");
    // Do not persist raw provider runtimeError messages or key material. HTTP200 is not Lighthouse success.
    if let Some(error)=l.get("runtimeError").filter(|v|!v.is_null()){ensure!(error.is_object(),"Invalid Lighthouse runtime error");return Ok(ParsedMetrics::RuntimeFailure);}
    let requested=optional_text(l,"requestedUrl",8192)?;let final_url=optional_text(l,"finalUrl",8192)?;for s in [&requested,&final_url].into_iter().flatten(){let u=url::Url::parse(s)?;ensure!(matches!(u.scheme(),"http"|"https")&&u.username().is_empty()&&u.password().is_none(),"Invalid provider URL");}
    let observed=PageSpeedMetrics{provider_requested_url:requested,provider_final_url:final_url,provider_fetch_time:optional_text(l,"fetchTime",128)?,lighthouse_version:optional_text(l,"lighthouseVersion",128)?,performance_score:metric(l,"/categories/performance/score",true)?,first_contentful_paint_ms:metric(l,"/audits/first-contentful-paint/numericValue",false)?,largest_contentful_paint_ms:metric(l,"/audits/largest-contentful-paint/numericValue",false)?,total_blocking_time_ms:metric(l,"/audits/total-blocking-time/numericValue",false)?,cumulative_layout_shift:metric(l,"/audits/cumulative-layout-shift/numericValue",false)?};
    if [observed.performance_score,observed.first_contentful_paint_ms,observed.largest_contentful_paint_ms,observed.total_blocking_time_ms,observed.cumulative_layout_shift].iter().all(Option::is_none){Ok(ParsedMetrics::Unavailable)}else{Ok(ParsedMetrics::Observed(observed))}
